WITH fn AS (SELECT p.oid,p.proacl,p.proowner,pg_get_functiondef(p.oid) definition FROM pg_proc p WHERE p.oid=to_regprocedure('public.cancel_mistaken_shipments_v1(uuid[],text)')) SELECT audit_issue,detail FROM(SELECT 'function_missing'::text audit_issue,'Thieu RPC cancel_mistaken_shipments_v1(uuid[],text)'::text detail WHERE NOT EXISTS(SELECT 1 FROM fn) UNION ALL SELECT 'admin_guard_missing','RPC khong con tu kiem tra quyen Admin' WHERE EXISTS(SELECT 1 FROM fn WHERE definition NOT ILIKE '%public.is_admin()%') UNION ALL SELECT 'date_window_missing','RPC khong gioi han hom nay va ngay lien truoc' WHERE EXISTS(SELECT 1 FROM fn WHERE definition NOT ILIKE '%s.shipment_date<v_today-1%' OR definition NOT ILIKE '%s.shipment_date>v_today%') UNION ALL SELECT 'next_day_guard_missing','RPC khong chan khi ngay sau da giao hoac da chot' WHERE EXISTS(SELECT 1 FROM fn WHERE definition NOT ILIKE '%Ngay sau da phat sinh giao hang hoac da chot%') UNION ALL SELECT 'soft_delete_missing','RPC khong con hieu hoa mem phieu giao hang' WHERE EXISTS(SELECT 1 FROM fn WHERE definition NOT ILIKE '%UPDATE public.shipment_logs SET deleted_at=%') UNION ALL SELECT 'audit_write_missing','RPC khong ghi lich su huy phieu' WHERE EXISTS(SELECT 1 FROM fn WHERE definition NOT ILIKE '%INSERT INTO public.shipment_cancellation_audit%') UNION ALL SELECT 'negative_stock_guard_missing','RPC khong con hau kiem am kho' WHERE EXISTS(SELECT 1 FROM fn WHERE definition NOT ILIKE '%inventory_assert_no_negative_product_after%') UNION ALL SELECT 'public_can_execute','PUBLIC van co quyen goi RPC' WHERE EXISTS(SELECT 1 FROM fn CROSS JOIN LATERAL aclexplode(COALESCE(fn.proacl,acldefault('f',fn.proowner))) acl WHERE acl.grantee=0 AND acl.privilege_type='EXECUTE') UNION ALL SELECT 'anon_can_execute','anon van co quyen goi RPC' WHERE to_regprocedure('public.cancel_mistaken_shipments_v1(uuid[],text)') IS NOT NULL AND has_function_privilege('anon','public.cancel_mistaken_shipments_v1(uuid[],text)','EXECUTE') UNION ALL SELECT 'authenticated_cannot_execute','authenticated khong the goi cong co hang rao Admin' WHERE to_regprocedure('public.cancel_mistaken_shipments_v1(uuid[],text)') IS NOT NULL AND NOT has_function_privilege('authenticated','public.cancel_mistaken_shipments_v1(uuid[],text)','EXECUTE')) problems ORDER BY audit_issue;
